args.sparql:
SELECT ?director ?directorLabel WHERE {
  dbr:Maggie_Pepper dbo:director ?director .
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = 'en') }
} LIMIT 10

SELECT ?deathPlace ?deathPlaceLabel WHERE {
  dbr:Chester_Withey dbo:deathPlace ?deathPlace .
  OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel FILTER(lang(?deathPlaceLabel) = 'en') }
} LIMIT 10

SELECT ?deathPlace ?deathPlaceLabel WHERE {
  dbr:Chester_Withey dbo:deathPlace ?deathPlace .
  OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel FILTER(lang(?deathPlaceLabel) = 'en') }
} LIMIT 10

output.sparql:
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT ?deathPlace ?deathPlaceLabel WHERE {
  dbr:Chester_Withey dbo:deathPlace ?deathPlace .
  OPTIONAL {
    ?deathPlace rdfs:label ?deathPlaceLabel
    FILTER(lang(?deathPlaceLabel) = 'en')
  }
}
LIMIT 10

